import csv
path='/root/weoapr2025all.xls'
with open(path, 'r', encoding='utf-16-le') as f:
    reader = csv.reader(f, delimiter='\t')
    header = next(reader)
    print('cols', len(header))
    print(header[:10])
    idx_country = header.index('Country')
    idx_iso = header.index('ISO')
    idx_subject = header.index('WEO Subject Code')
    subjects = {'NGDP_R', 'NGDP_RPCH', 'NGDP_D'}
    rows = {s: None for s in subjects}
    for row in reader:
        if row[idx_country] == 'Georgia' and row[idx_subject] in subjects:
            rows[row[idx_subject]] = row
            if all(rows.values()):
                break
    print('found', {k: (v is not None) for k,v in rows.items()})
    years = [str(y) for y in range(2020, 2030)]
    year_idx = {y: header.index(y) for y in years if y in header}
    for k, row in rows.items():
        if row:
            print(k, [row[year_idx[str(y)]] for y in range(2020, 2030)])
